        } | ConvertTo-Json)

    Fail "Should have been blocked by fraud service!"
} catch {
    $rawErr = $_.ErrorDetails.Message
    try {
        $e = $rawErr | ConvertFrom-Json
        if ($e.detail.code -eq "fraud